<template>
  <main class="writing-page">
    <DocumentStudioChrome :current="completed ? 4 : 3" :project-name="projectName" :busy="running || starting" :assistant-items="assistantItems" :description="completed ? '文档已完成，可以下载 Word。' : '正在并行生成正文并检查图表和格式。'" />
    <header><span>STEP 3 · AI WRITING</span><h1>纯文字稿生成中心</h1><p>所有二级标题同时启动独立分支，随后完成原生图表和 Word 质检。300 积分 / 篇，生成成功后扣费。</p></header>

    <section class="project-overview panel">
      <div class="project-identity"><small>当前项目</small><h2>{{ projectName }}</h2><p>{{ stage }}</p><div class="context-stats"><span>章节数量<b>{{ chapters.length }}</b></span><span>并行分支<b>{{ branchCount }}</b></span><span>原生图表<b>{{ chartCount }}</b></span><span>原生表格<b>{{ tableCount }}</b></span></div></div>
      <div class="overall-progress"><div><span>任务进度</span><b>{{ statusLabel }}<small v-if="running"> · 已等待 {{ elapsedLabel }}</small></b></div><strong>{{ progress }}<small>%</small></strong><div class="progress-track"><i :style="{width:`${progress}%`}"></i></div><p v-if="running">页面可安全刷新，任务状态会自动恢复</p></div>
    </section>

    <section class="writing-grid">
      <div class="writing-main">
        <section class="control-card panel">
          <div class="section-head"><div><small>GENERATION CONTROL</small><h2>生成控制中心</h2></div><span>{{ running ? 'AI 正在写作' : completed ? '生成完成' : '准备就绪' }}</span></div>
          <div class="output-items"><div v-for="(item,index) in outputItems" :key="item" :class="checkState(index)"><i>{{ checkState(index)==='done'?'✓':checkState(index)==='active'?'●':'○' }}</i><span>{{ item }}</span><small>{{ checkStateText(index) }}</small></div></div>
          <button v-if="!running&&!completed" class="primary-action" type="button" :disabled="starting" @click="start">{{ starting ? '正在启动…' : failed ? '重新开始生成' : '开始生成' }}</button>
          <button v-else-if="running" class="primary-action running-button" type="button" disabled>生成中</button>
          <button v-else-if="completed" class="primary-action" type="button" @click="scrollResult">查看结果</button>
          <div v-if="running" class="active-task"><i></i><div><b>{{ stage }}</b><span>{{ displayMessage }} · 已等待 {{ elapsedLabel }}</span></div></div>
          <div v-if="failed" class="soft-warning"><b>任务已暂停</b><p>{{ displayMessage }}。可以调整后重新生成，格式类问题将自动修复。</p></div>
        </section>

        <section class="chapter-progress panel">
          <div class="section-head"><div><small>CHAPTER PROGRESS</small><h2>章节级进度</h2></div><span>{{ completedChapters }}/{{ chapters.length }} 章完成</span></div>
          <div class="chapter-list"><article v-for="(chapter,index) in chapters" :key="chapter.id || index" :class="chapterStatus(index)"><i>{{ chapterStatus(index)==='done' ? '✓' : index+1 }}</i><div class="chapter-copy"><b>第 {{ chapter.chapter_no || index+1 }} 章 · {{ cleanTitle(chapter.title) }}</b><span><small>{{ chapter.sections?.length || 0 }} 个二级标题</small><small>{{ chapter.charts?.length || 0 }} 张原生图表</small><small>{{ chapter.tables?.length || 0 }} 张表格</small></span></div><em>{{ chapterStatusText(index) }}</em><div class="chapter-line"><span :style="{width:`${chapterProgress(index)}%`}"></span></div></article></div>
        </section>

        <section class="live-log panel">
          <div class="section-head"><div><small>LIVE AI LOG</small><h2>实时 AI 日志</h2></div><span class="live-dot">{{ running ? '实时更新' : '任务记录' }}</span></div>
          <div class="log-list"><div v-for="item in logItems" :key="item.label" :class="item.state"><i>{{ item.state==='done'?'✓':item.state==='active'?'···':'○' }}</i><span><b>{{ item.label }}</b><small>{{ item.message }}</small></span><time>{{ item.state==='done'?'已完成':item.state==='active'?'进行中':'等待' }}</time></div></div>
        </section>
      </div>

      <aside class="writing-side">
        <section class="basis-card panel"><small>WRITING BASIS</small><h3>生成依据</h3><div><span>并行分支<b>{{ branchCount }}</b></span><span>原生图表<b>{{ chartCount }}</b></span><span>原生表格<b>{{ tableCount }}</b></span><span>章节数量<b>{{ chapters.length }}</b></span></div></section>
        <section class="quality-card panel"><small>QUALITY CHECK</small><h3>自动质量规范</h3><ul><li v-for="item in qualityItems" :key="item.label"><i>{{ completed?'✓':running?'···':'○' }}</i><span><b>{{ item.label }}</b><small>{{ completed?'已完成':running?'正在检查':'等待检查' }}</small></span></li></ul><p>字数或图表未达要求时会明确提示，避免交付不合格稿件。</p></section>
      </aside>
    </section>

    <section v-if="completed" id="export" class="result-card panel">
      <div class="docx-icon">W</div><div><small>FINAL DOCUMENT</small><h2>{{ projectName }}.docx</h2><p>正文、原生图表与表格已合并完成。</p><div class="result-checks"><span v-for="item in qualityItems" :key="item.label">✓ {{ item.label }}</span></div></div><div class="result-actions"><button type="button" @click="preview">在线预览</button><button class="primary-action" type="button" @click="download">下载 DOCX</button></div>
    </section>
  </main>
</template>

<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRouter } from 'vue-router'
import DocumentStudioChrome from '../../components/DocumentStudioChrome.vue'
import { downloadArtifact, getWritingProgress, getWritingProject, startWritingGeneration } from '../../api/rewrite'

const router=useRouter();const id=sessionStorage.getItem('dropai_writing_project_id')||localStorage.getItem('dropai_writing_project_id')||''
const flow=ref({chapters:[],references:[]});const starting=ref(false);const status=ref('WAITING');const stage=ref('等待开始');const serverProgress=ref(0);const progress=ref(0);const message=ref('大纲已确认，正在准备生成。');const downloadUrl=ref('');const elapsedSeconds=ref(0);let timer=null;let uiTimer=null
const startedAtKey=`dropai_writing_started_at_${id}`
const outputItems=['全部分支并行写作','原生图表与表格','组装正文','DOCX 质检'];const qualityItems=[{label:'章节完整'},{label:'字数达标'},{label:'原生图表'},{label:'目录与格式'}]
const running=computed(()=>status.value==='RUNNING');const completed=computed(()=>status.value==='SUCCESS');const failed=computed(()=>status.value==='FAILED')
const chapters=computed(()=>flow.value.chapters||[]);const projectName=computed(()=>flow.value.title||sessionStorage.getItem('writing_project_title')||localStorage.getItem('writing_project_title')||'未命名项目')
const branchCount=computed(()=>chapters.value.reduce((sum,chapter)=>sum+(chapter.sections?.length||0),0));const chartCount=computed(()=>chapters.value.reduce((sum,chapter)=>sum+(chapter.charts?.length||0),0));const tableCount=computed(()=>chapters.value.reduce((sum,chapter)=>sum+(chapter.tables?.length||0),0));const completedChapters=computed(()=>chapters.value.filter((_,index)=>chapterStatus(index)==='done').length)
const statusLabel=computed(()=>completed.value?'生成完成':failed.value?'生成失败':running.value?'正文生成中':'准备生成');const displayMessage=computed(()=>message.value)
const elapsedLabel=computed(()=>{const minutes=Math.floor(elapsedSeconds.value/60);const seconds=elapsedSeconds.value%60;return minutes?`${minutes}分${String(seconds).padStart(2,'0')}秒`:`${seconds}秒`})
const assistantItems=computed(()=>[{label:'整体进度',value:`${progress.value}%`},{label:'写作分支',value:`${branchCount.value} 个同时启动`},{label:'完成章节',value:`${completedChapters.value}/${chapters.value.length}`},{label:'质量规范',value:completed.value?'已完成':running.value?'进行中':'待执行'}])
const logItems=computed(()=>{const p=progress.value;return[{label:'分支写作',message:`${branchCount.value} 个二级标题同时生成`,state:completed.value||p>=72?'done':p>=28&&running.value?'active':'waiting'},{label:'原生图表与表格',message:`配置 ${chartCount.value} 张原生图表`,state:completed.value||p>=84?'done':p>=72&&running.value?'active':'waiting'},{label:'组装正文',message:'按大纲顺序写回并制作 Word',state:completed.value||p>=92?'done':p>=84&&running.value?'active':'waiting'},{label:'DOCX 质检',message:'字数、目录和图表检查',state:completed.value?'done':p>=92&&running.value?'active':'waiting'}]})
function chapterProgress(){if(completed.value||progress.value>=72)return 100;if(progress.value<28)return 0;return Math.min(95,Math.max(5,(progress.value-28)/44*95))}
function chapterStatus(index){const value=chapterProgress(index);return value>=100?'done':value>0?'active':'waiting'}function chapterStatusText(index){return({done:'完成',active:'生成中',waiting:'等待'})[chapterStatus(index)]}
function checkState(index){if(completed.value)return'done';if(!running.value)return'waiting';const threshold=[28,72,84,92][index]||0;const next=[72,84,92,101][index]||101;return progress.value>=next?'done':progress.value>=threshold?'active':'waiting'}
function checkStateText(index){return({waiting:'未开始',active:'处理中',done:'完成'})[checkState(index)]}
function scrollResult(){router.push('/writing-generator/export')}
function cleanTitle(value){return String(value||'').replace(/^\d+(\.\d+)?\s*/,'').replace(/^第[一二三四五六七八九十\d]+章\s*/,'')}
async function load(){if(!id){ElMessage.warning('项目不存在');return router.push('/writing')}try{const [project,data]=await Promise.all([getWritingProject(id),getWritingProgress(id)]);flow.value=project||{chapters:[],references:[]};applyProgress(data);if(status.value==='RUNNING')poll()}catch(error){ElMessage.error(error?.responseData?.message||error?.message||'生成状态读取失败')}}
async function start(){if(!id)return router.push('/writing');starting.value=true;try{localStorage.setItem(startedAtKey,String(Date.now()));startUiTicker();const data=await startWritingGeneration(id);applyProgress(data);if(status.value==='RUNNING')poll()}catch(error){ElMessage.error(error?.responseData?.message||error?.message||'任务启动失败')}finally{starting.value=false}}
function applyProgress(data){if(!data)return;status.value=String(data.status||status.value).toUpperCase();stage.value=data.current_stage||data.stage||stage.value;serverProgress.value=Number(data.progress??serverProgress.value);progress.value=Math.max(progress.value,serverProgress.value);message.value=data.error_message||data.message||stage.value;downloadUrl.value=data.files?.[0]?.download_url||downloadUrl.value;if(running.value){if(!localStorage.getItem(startedAtKey))localStorage.setItem(startedAtKey,String(Date.now()));startUiTicker()}else{progress.value=completed.value?100:serverProgress.value;stopUiTicker();localStorage.removeItem(startedAtKey)}}
function progressCap(){const p=serverProgress.value;if(p<28)return 27;if(p<72)return 70;if(p<84)return 83;if(p<92)return 91;if(p<97)return 96;return 99}
function tickUi(){const started=Number(localStorage.getItem(startedAtKey)||Date.now());elapsedSeconds.value=Math.max(0,Math.floor((Date.now()-started)/1000));if(running.value&&progress.value<progressCap())progress.value=Math.min(progressCap(),progress.value+1)}
function startUiTicker(){if(uiTimer)return;tickUi();uiTimer=setInterval(tickUi,1400)}
function stopUiTicker(){if(uiTimer){clearInterval(uiTimer);uiTimer=null}}
function poll(){clearTimeout(timer);timer=setTimeout(async()=>{try{const data=await getWritingProgress(id);applyProgress(data);if(status.value==='RUNNING')poll()}catch(error){message.value='进度读取失败，正在重试';poll()}},1800)}
async function getArtifact(){if(!downloadUrl.value)throw new Error('DOCX 文件尚未就绪');return downloadArtifact(downloadUrl.value)}
async function download(){try{const blob=await getArtifact();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${projectName.value.replace(/[\\/:*?"<>|]/g,'_')}.docx`;a.click();URL.revokeObjectURL(url)}catch(error){ElMessage.warning(error.message)}}
async function preview(){try{const blob=await getArtifact();const url=URL.createObjectURL(blob);window.open(url,'_blank','noopener,noreferrer');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){ElMessage.warning(error.message)}}
onMounted(load);onUnmounted(()=>{clearTimeout(timer);stopUiTicker()})
</script>

<style scoped>
